def drop_all_schema_objects_post_tables(cfg, eng):
    from sqlalchemy.dialects import postgresql
    inspector = inspect(eng)
    with eng.begin() as conn:
        for enum in inspector.get_enums("*"):
            conn.execute(
                postgresql.DropEnumType(
